export const breadcrumbCss = ".kalos-breadcrumb{font-family:Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", ByteSans, Arial, "Helvetica Neue", -apple-system, BlinkMacSystemFont, "noto sans", Helvetica, sans-serif;--bc-radius:4px;--bc-chevron:12px;--bc-moreWidth:24px;--bc-moreHeight:20px;--bc-menuWidth:168px;--bc-menuRadius:12px;--bc-menuPadding:4px;--bc-rowHeight:32px;--bc-rowRadius:8px;--bc-rowIcon:15px;--bc-touchRow:40px;--bc-fontSize:13px;--bc-labelWidth:200px;--bc-hoverDuration:120ms;--bc-currentDuration:260ms;--bc-menuDuration:220ms;--bc-ease:cubic-bezier(0.22, 1, 0.36, 1);--bc-ink:rgba(0, 0, 0, 0.88);--bc-muted:rgba(0, 0, 0, 0.45);--bc-faint:rgba(0, 0, 0, 0.27);--bc-wash:rgba(0, 0, 0, 0.04);--bc-surface:#ffffff;--bc-text:rgba(0, 0, 0, 0.61);--bc-glow:rgba(0, 0, 0, 0.035);--bc-shadow:0 0 0 0.5px rgba(0, 0, 0, 0.1), 0 12px 32px -8px rgba(0, 0, 0, 0.16);--bc-focus:rgba(0, 96, 226, 0.7);--bc-icon:rgba(0, 0, 0, 0.45)}
:where(.dark,[data-theme=dark]) .kalos-breadcrumb{--bc-ink:rgba(255, 255, 255, 0.9);--bc-muted:rgba(255, 255, 255, 0.45);--bc-faint:rgba(255, 255, 255, 0.28);--bc-wash:rgba(255, 255, 255, 0.06);--bc-surface:#1b1b1e;--bc-text:rgba(255, 255, 255, 0.62);--bc-glow:rgba(255, 255, 255, 0.06);--bc-shadow:0 0 0 0.5px rgba(255, 255, 255, 0.14), 0 12px 32px -8px rgba(0, 0, 0, 0.6);--bc-focus:rgba(77, 141, 255, 0.8);--bc-icon:rgba(255, 255, 255, 0.45)}
.kalos-breadcrumb {
  position: relative;
  display: block;
  min-width: 0;
  font-size: var(--bc-fontSize);
  line-height: 20px;
  font-weight: 400;
  color: var(--bc-muted);
  -webkit-font-smoothing: antialiased;
}
.kalos-breadcrumb *, .kalos-breadcrumb *::after { box-sizing: border-box; }
.kalos-breadcrumb-list {
  display: flex;
  align-items: center;
  min-width: 0;
  margin: 0;
  padding: 0;
  list-style: none;
  white-space: nowrap;
}
.kalos-breadcrumb-item { display: flex; flex: none; align-items: center; min-width: 0; }
.kalos-breadcrumb-item[data-current] { flex: 0 1 auto; }
/* Leave room for the current page even if the root name alone would fill the row. */
.kalos-breadcrumb-list[data-tight] > :first-child:not(:last-child) { max-width: max(0px, calc(100% - 80px)); }
.kalos-breadcrumb-list[data-tight] > :first-child:nth-last-child(3) { max-width: max(0px, calc(100% - 40px)); }
.kalos-breadcrumb-separator {
  display: grid;
  flex: none;
  place-items: center;
  min-width: 20px;
  padding: 0 2px;
  color: var(--bc-faint);
  user-select: none;
}
.kalos-breadcrumb-separator svg { display: block; width: var(--bc-chevron); height: var(--bc-chevron); }
.kalos-breadcrumb-chevron:dir(rtl), .kalos-breadcrumb-nest:dir(rtl) { transform: scaleX(-1); }
.kalos-breadcrumb-link, .kalos-breadcrumb-current, .kalos-breadcrumb-more {
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--bc-radius);
  background: transparent;
  font: inherit;
  color: inherit;
  text-decoration: none;
  -webkit-tap-highlight-color: transparent;
}
.kalos-breadcrumb-link, .kalos-breadcrumb-current {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  max-width: 100%;
}
.kalos-breadcrumb-link:is(a, button) { cursor: pointer; transition: color var(--bc-hoverDuration) ease; }
.kalos-breadcrumb-link:is(a, button):hover { color: var(--bc-ink); }
.kalos-breadcrumb-current {
  color: var(--bc-ink);
  font-weight: 500;
  animation: kalos-breadcrumb-enter var(--bc-currentDuration) var(--bc-ease) both;
}
.kalos-breadcrumb-label, .kalos-breadcrumb-row-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.kalos-breadcrumb-label { max-width: var(--bc-labelWidth); }
.kalos-breadcrumb-current .kalos-breadcrumb-label { max-width: none; }
.kalos-breadcrumb-icon, .kalos-breadcrumb-row-icon { display: grid; flex: none; place-items: center; }
.kalos-breadcrumb-icon, .kalos-breadcrumb-icon > :is(svg, img) { width: 14px; height: 14px; }
.kalos-breadcrumb-more {
  position: relative;
  display: grid;
  place-items: center;
  width: var(--bc-moreWidth);
  height: var(--bc-moreHeight);
  cursor: pointer;
  transition: background-color var(--bc-hoverDuration) ease, color var(--bc-hoverDuration) ease;
}
.kalos-breadcrumb-more:hover, .kalos-breadcrumb-more[aria-expanded=true] { background: var(--bc-wash); color: var(--bc-ink); }
.kalos-breadcrumb-more svg { width: 16px; height: 16px; }
.kalos-breadcrumb-more:focus-visible, .kalos-breadcrumb-link:focus-visible { outline: 2px solid var(--bc-focus); outline-offset: 2px; }

.kalos-breadcrumb-positioner {
  inset: auto;
  z-index: 1000;
  width: max-content;
  height: auto;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  overflow: visible;
}
.kalos-breadcrumb-positioner::backdrop { display: none; }
.kalos-breadcrumb-menu {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-content: start;
  gap: 1px;
  min-width: min(var(--bc-menuWidth), calc(100vw - 16px));
  max-width: min(320px, calc(100vw - 16px));
  max-height: var(--available-height, calc(100dvh - 16px));
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: var(--bc-menuPadding);
  border: 0;
  border-radius: var(--bc-menuRadius);
  background: var(--bc-surface);
  color: var(--bc-text);
  box-shadow: var(--bc-shadow);
  outline: none;
  font: inherit;
  transform-origin: left top;
}
.kalos-breadcrumb-menu[data-open] { animation: kalos-breadcrumb-menu-enter var(--bc-menuDuration) var(--bc-ease) both; }
.kalos-breadcrumb-menu[data-side=top] { --bc-menu-shift: 4px; transform-origin: left bottom; }
.kalos-breadcrumb-menu:dir(rtl) { transform-origin: right top; }
.kalos-breadcrumb-menu[data-side=top]:dir(rtl) { transform-origin: right bottom; }
.kalos-breadcrumb-row {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  min-height: var(--bc-rowHeight);
  margin: 0;
  padding: 0 10px;
  padding-inline-start: calc(10px + var(--bc-depth) * 12px);
  border: 0;
  border-radius: var(--bc-rowRadius);
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: start;
  text-decoration: none;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  transition: background-color var(--bc-hoverDuration) ease, color var(--bc-hoverDuration) ease;
}
.kalos-breadcrumb-row:not([aria-disabled=true]):is(:hover,:focus,[data-highlighted]) { background: var(--bc-glow); color: var(--bc-ink); }
.kalos-breadcrumb-row:focus-visible { outline: 2px solid var(--bc-focus); outline-offset: -2px; }
.kalos-breadcrumb-row[aria-disabled=true] { cursor: default; }
.kalos-breadcrumb-row-icon { width: 16px; height: 16px; color: var(--bc-icon); }
.kalos-breadcrumb-row-icon > :is(svg, img) { width: var(--bc-rowIcon); height: var(--bc-rowIcon); }

/* Measure text at its natural width, independently from the visible, truncated trail. */
.kalos-breadcrumb-measure { position: absolute; inset: 0; visibility: hidden; overflow: hidden; pointer-events: none; }
.kalos-breadcrumb-sizes { display: flex; width: max-content; white-space: nowrap; }
.kalos-breadcrumb-sizes > span { flex: none; max-width: var(--bc-labelWidth); overflow: hidden; box-sizing: content-box; }
.kalos-breadcrumb-sizes > span[data-icon] { padding-inline-start: 20px; }
.kalos-breadcrumb-sizes > :last-child { font-weight: 500; }
@keyframes kalos-breadcrumb-enter { from { opacity: 0; transform: translateX(-4px); } }
@keyframes kalos-breadcrumb-menu-enter { from { opacity: 0; transform: scale(.96) translateY(var(--bc-menu-shift, -4px)); } }
@media (pointer: coarse) {
  .kalos-breadcrumb-link:is(a, button) { position: relative; }
  .kalos-breadcrumb-link:is(a, button)::after { content: ""; position: absolute; inset: -10px -4px; }
  .kalos-breadcrumb-more::after { content: ""; position: absolute; inset: -8px -6px; }
  .kalos-breadcrumb-row { min-height: var(--bc-touchRow); }
}
";
export const breadcrumbMaxItems = 4;
